 herb1:{x:280,y:200,name:'Bitterroot',role:'WILD HERB',icon:'❋',color:'#778a63'},herb2:{x:645,y:185,name:'Bitterroot',role:'WILD HERB',icon:'❋',color:'#778a63'},herb3:{x:765,y:463,name:'Bitterroot',role:'WILD HERB',icon:'❋',color:'#778a63'}
};
function log(text){game.logs.unshift({time:clock(),text});game.logs=game.logs.slice(0,20);renderJournal()}
function clock(){let h=Math.floor(game.time/60),m=game.time%60;return `${String(h%12||12).padStart(2,'0')}:${String(m).padStart(2,'0')}`}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function setStatus(text){$('#status-line').textContent=text}
function setQuest(title,obj){$('#quest-title').textContent=title;$('#quest-objective').textContent=obj;$('#journal-title').textContent=title;$('#journal-objective').textContent=obj}
function addXP(n){game.xp+=n;while(game.xp>=game.level*100){game.xp-=game.level*100;game.level++;game.maxHp+=8;game.maxChakra+=5;game.power++;game.hp=game.maxHp;game.chakra=game.maxChakra;$('#level-toast').classList.remove('hidden');setTimeout(()=>$('#level-toast').classList.add('hidden'),2100);toast(`Level ${game.level} · your resolve deepens.`)}renderUI();save()}
function addItem(name,n=1){game.player.items[name]=(game.player.items[name]||0)+n;toast(`${name} ×${n} added to your pack`);renderUI()}
function useItem(name){const n=game.player.items[name]||0;if(!n)return false;game.player.items[name]--;if(game.player.items[name]<=0)delete game.player.items[name];if(name==='Field Ration'){game.player.hp=Math.min(game.player.maxHp,game.player.hp+32);game.player.stamina=game.player.maxStamina;toast('A quiet moment. Vitality restored.')}else if(name==='Bitterroot Leaf'){game.player.chakra=Math.min(game.player.maxChakra,game.player.chakra+18);toast('The bitter tea steadies your chakra.')}renderUI();return true}
function save(){try{const p={...game,keys:{},enemies:[],projectiles:[],particles:[],near:null};localStorage.setItem('riftbound-save',JSON.stringify(p));$('#save-btn').classList.add('saved');setTimeout(()=>$('#save-btn').classList.remove('saved'),700)}catch(e){}}
function load(){try{const raw=localStorage.getItem('riftbound-save');if(!raw)return false;const d=JSON.parse(raw);Object.assign(game,d);game.keys={};game.enemies=[];game.projectiles=[];game.particles=[];game.started=true;setArea(game.area,false);return true}catch(e){return false}}
function renderJournal(){$('#journal-log').innerHTML=game.logs.map(a=>`<p><span>${a.time}</span> ${escapeHTML(a.text)}</p>`).join('')}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderInventory(){const entries=Object.entries(game.player.items||{});$('#item-count').textContent=entries.reduce((a,[,n])=>a+n,0);$('#pack-weight').textContent=`${entries.reduce((a,[,n])=>a+n,0)} / 20`;const icons={'Field Ration':'◒','Bitterroot Leaf':'❋','Sealed Scroll':'▤','Old Coin':'◉'};$('#inventory-list').innerHTML=entries.length?entries.map(([name,n])=>`<div class="inventory-item"><div class="item-icon">${icons[name]||'◇'}</div><div><b>${escapeHTML(name)}</b><small>${name==='Field Ration'?'Restores vitality':name==='Bitterroot Leaf'?'Restores chakra':name==='Sealed Scroll'?'A message from another time':'A small keepsake'}</small></div><span class="item-qty">×${n}</span>${['Field Ration','Bitterroot Leaf'].includes(name)?`<button class="use-item" data-item="${name}">USE</button>`:''}</div>`).join(''):'<p class="muted-note">Nothing but dust in your pack.</p>';$$('.use-item').forEach(b=>b.onclick=()=>useItem(b.dataset.item))}
function renderUI(){const p=game.player;$('#player-name').textContent=p.name;$('#player-rank').textContent=`${game.flags.registered?'GENIN':'UNREGISTERED'} · LV ${p.level}`;$('#portrait').textContent=(p.name||'?').slice(0,1).toUpperCase();$('#portrait').style.background=p.hair;$('#hp-text').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}`;$('#chakra-text').textContent=`${Math.ceil(p.chakra)} / ${p.maxChakra}`;$('#stamina-text').textContent=`${Math.ceil(p.stamina)} / ${p.maxStamina}`;$('#hp-bar').style.width=`${100*p.hp/p.maxHp}%`;$('#chakra-bar').style.width=`${100*p.chakra/p.maxChakra}%`;$('#stamina-bar').style.width=`${100*p.stamina/p.maxStamina}%`;$('#stat-level').textContent=String(p.level).padStart(2,'0');$('#stat-xp').textContent=`${p.xp} / ${p.level*100}`;$('#stat-renown').textContent=p.renown;$('#stat-coin').textContent=`${p.coins} RYO`;$('#stat-power').textContent=p.power;$('#stat-control').textContent=p.control;$('#stat-resolve').textContent=p.resolve;$('#bond-value').textContent=`${p.bond} / 100`;$('#bond-bar').style.width=`${p.bond}%`;$('#kunai-count').textContent=p.kunai;$('#bond-note').textContent=p.bond<20?'A first impression is waiting to be made.':p.bond<60?'Iruka has begun to trust you with the truth.':'You have earned a place at the village table.';renderInventory();renderJournal();updateQuest();updateMiniMap()}
function updateQuest(){const q=game.quest;if(q===0)setQuest('A Stranger in the Leaves','Find the village instructor.');if(q===1)setQuest('A Stranger in the Leaves','Investigate the strange rift scar to the west.');if(q===2)setQuest('Echoes in the Pines',`Find the sealed scroll at the forest camp. Threats defeated: ${game.kills} / 2.`);if(q===3)setQuest('The Message Between Worlds','Return the sealed scroll to Iruka.');if(q===4)setQuest('A Place to Begin','Speak with Iruka to choose your next step.');if(q===5)setQuest('Fieldwork: Bitterroot','Gather bitterroot from the forest (0 / 3).');if(q===6)setQuest('Fieldwork: Bitterroot','Return three bitterroot leaves to Sakura.');if(q>=7)setQuest('A Place to Begin','Explore the village, make friends, and decide what home means.');}
function updateMiniMap(){$('#mini-map').classList.toggle('forest',game.area==='forest');}
function setArea(area,announce=true){game.area=area;const p=game.player;if(area==='forest')p.x=76,p.y=300;else p.x=875,p.y=300;$('#region-label').textContent=areas[area].region;$('#location-name').textContent=areas[area].name;$('#weather-label').textContent=areas[area].weather;game.enemies=[];if(area==='forest'){if(game.quest>=2&&game.quest<=3)spawnEnemies();else if(game.quest>=5&&game.quest<=6)spawnEnemies(true)}if(announce){toast(area==='forest'?'You pass beyond the village gate.':'The familiar rooftops rise ahead.');log(`Entered ${areas[area].name}.`);save()}}
function spawnEnemies(side=false){const dead=game.flags.banditsCleared&&game.quest<5;if(dead&&!side)return;game.enemies=[{x:430,y:286,hp:side?36:48,max:side?36:48,kind:'Rogue',cool:0,hit:false},{x:620,y:404,hp:side?36:48,max:side?36:48,kind:'Rogue',cool:0,hit:false}];if(game.flags.banditsCleared&&side)game.enemies=[{x:550,y:340,hp:40,max:40,kind:'Rogue',cool:0,hit:false}];}

input.newString:
function spawnEnemies(side=false){const dead=game.flags.banditsCleared&&game.quest<5;if(dead&&!side)return;game.enemies=[{x:430,y:286,hp:side?36:48,max:side?36:48,kind:'Rogue',cool:0,hit:false},{x:620,y:404,hp:side?36:48,max:side?36:48,kind:'Rogue',cool:0,hit:false}];if(game.flags.banditsCleared&&side)game.enemies=[{x:550,y:340,hp:40,max:40,kind:'Rogue',cool:0,hit:false}];}
const rnd=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function closeTo(a,b,r=57){return Math.hypot(a.x-b.x,a.y-b.y)<r}
function candidates(){if(game.area==='village')return Object.entries(npcs).filter(([id])=>!id.startsWith('herb'));return Object.entries(npcs).filter(([id])=>id==='herb1'||id==='herb2'||id==='herb3'||id==='cache'||id==='rift')}
function nearest(){let best=null,dist=1000;for(const [id,n] of candidates()){if(['herb1','herb2','herb3'].includes(id)&&game.flags[id])continue;if(id==='cache'&&(game.quest!==2||game.kills<2))continue;const d=Math.hypot(n.x-game.player.x,n.y-game.player.y);if(d<dist&&d<72){best={id,n,d};dist=d}}for(const e of game.enemies){const d=Math.hypot(e.x-game.player.x,e.y-game.player.y);if(d<dist&&d<62){best={id:'enemy',n:e,d};dist=d}}return best}
function interact(){if(game.dialogueOpen)return;const t=game.near=nearest();if(!t){toast('Nothing close enough to interact with.');return}if(t.id==='enemy'){toast('A strike or kunai will make them back off.');return}if(t.id==='gate'){if(game.area==='village'){if(game.quest===1){beginDialogue('Gate','The gate guard watches the road.','The western trail is unsettled. That strange light you mentioned? It came from the forest. Move carefully.',[{text:'Head into the forest',fn:()=>setArea('forest')},{text:'Not yet',fn:closeDialogue}])}else beginDialogue('Gate','The gate guard watches the road.','The road beyond the trees runs toward the Land of Fire. Keep your eyes open—and come back before dark.',[{text:'Enter the forest',fn:()=>setArea('forest')},{text:'Stay in the village',fn:closeDialogue}])}return}
if(t.id==='rift'){if(game.quest===1){beginDialogue('The Rift Scar','The air folds in on itself. For a moment, you hear traffic, rain, a life you almost recognize.','The fracture hums against your skin. A strip of paper has caught on the roots nearby. There are fresh footprints leading deeper into the pines.',[{text:'Take a closer look · Control check',fn:()=>{game.player.chakra=Math.max(0,game.player.chakra-4);game.quest=2;game.flags.riftStudied=true;game.player.control++;log('You studied the rift. The paper bears a village seal—and a date from tomorrow.');addXP(20);closeDialogue();toast('New lead: search the rogue camp in the forest.')}} ,{text:'Back away and follow the tracks',fn:()=>{game.quest=2;game.flags.riftStudied=true;log('You chose to follow the footprints.');closeDialogue();}}])}else beginDialogue('The Rift Scar','A faint shimmer lingers among the roots.','The air is quiet now, though you still feel a strange pull toward the life you left behind.',[{text:'Remember this moment',fn:()=>{game.player.resolve++;closeDialogue();toast('Resolve +1');}} ,{text:'Leave it be',fn:closeDialogue}]);return}
if(t.id.startsWith('herb')){game.flags[t.id]=true;game.herbs++;addItem('Bitterroot Leaf');log('Gathered bitterroot.');if(game.quest===5&&game.herbs>=3){game.quest=6;toast('Three bitterroot leaves gathered. Take them to Sakura.')}else if(game.quest>=7)toast('Herb gathered for later.');renderUI();save();return}
if(t.id==='cache'){if(game.quest===2&&game.kills>=2){addItem('Sealed Scroll');game.quest=3;game.flags.scrollFound=true;log('The sealed scroll was tucked beneath the camp ledger. Its seal matches the mark by the rift.');addXP(35);toast('Scroll secured. Return to Iruka.');save();renderUI()}return}
if(t.id==='iruka'){talkIruka();return}if(t.id==='sakura'){talkSakura();return}if(t.id==='merchant'){talkMerchant();return}}
function beginDialogue(name,role,text,choices,icon){game.dialogueOpen=true;$('#dialogue').classList.remove('hidden');$('#dialogue-name').textContent=name;$('#dialogue-role').textContent=role.toUpperCase();$('#dialogue-avatar').textContent=icon||name.slice(0,1);$('#dialogue-text').textContent=text;const box=$('#dialogue-choices');box.innerHTML='';choices.forEach(c=>{const b=document.createElement('button');b.textContent=c.text;b.onclick=()=>c.fn();box.appendChild(b)});$('#interaction-hint').classList.add('hidden')}
function closeDialogue(){game.dialogueOpen=false;$('#dialogue').classList.add('hidden');save()}
function talkIruka(){if(game.quest===0){beginDialogue('Iruka','VILLAGE INSTRUCTOR','You came to in the training field with no village papers and a story about a sky that split open. I have heard stranger things—but not many. What do people call you?',[
{text:'I am '+game.player.name+'. I came from another world.',fn:()=>{game.player.bond+=12;game.player.renown+=2;game.flags.registered=true;game.quest=1;game.player.hp=Math.max(game.player.hp,game.player.maxHp*.7);log('Iruka listened without laughing. He asked you to inspect the western forest.');addXP(15);setStatus('Someone believes you. That matters more than you expected.');closeDialogue();toast('Story updated · investigate the rift scar.')}},
{text:'Just a traveler. I need somewhere safe.',fn:()=>{game.player.bond+=6;game.player.resolve++;game.flags.registered=true;game.quest=1;log('You kept the story close. Iruka offered shelter while you investigate the strange light.');closeDialogue();toast('Iruka points you toward the western forest.')}}])}
else if(game.quest===3){beginDialogue('Iruka','VILLAGE INSTRUCTOR','You found it. The seal is from the old archive—but the date written beneath it is tomorrow. Someone knew the rift would open before it did. What should we do with this?',[
{text:'Keep the village safe. I will help.',fn:()=>finishMain(18)},
{text:'I want to understand the way home.',fn:()=>{game.player.bond+=8;game.player.resolve++;finishMain(12);log('You admitted that finding a way home matters too. Iruka did not ask you to give that up.')}}])}
else if(game.quest===4){beginDialogue('Iruka','VILLAGE INSTRUCTOR','You have a place here as long as you want one. A small supply run could help you learn the trails—or you can take the day for yourself.',[
{text:'I will gather herbs for Sakura.',fn:()=>{game.quest=5;game.herbs=0;game.flags.herb1=game.flags.herb2=game.flags.herb3=false;log('Iruka asked you to collect bitterroot for Sakura at the medical station.');closeDialogue();setArea('forest');toast('Fieldwork accepted · gather 3 bitterroot leaves.')}},
{text:'Tell me more about the rift.',fn:()=>{game.player.bond+=4;beginDialogue('Iruka','VILLAGE INSTRUCTOR','The rift is not just a door. The paper you brought carries a date that has not come yet. Whatever made it may be able to change what comes next.',[{text:'I understand.',fn:closeDialogue},{text:'I need time to think.',fn:closeDialogue}])}},
{text:'I need a quiet moment.',fn:()=>{closeDialogue();rest(true)}}])}
else if(game.quest===6){beginDialogue('Iruka','VILLAGE INSTRUCTOR','Sakura is waiting for those herbs. She will be grateful—and she has a way of showing it.',[{text:'I will find her.',fn:()=>{closeDialogue();setArea('village');toast('Return to Sakura near the training field.')}},{text:'Later.',fn:closeDialogue}])}
else beginDialogue('Iruka','VILLAGE INSTRUCTOR','You do not owe this village your whole life. But while you are here, we will look out for one another. That is what a village is.',[{text:'Thank you, Iruka.',fn:()=>{game.player.bond=Math.min(100,game.player.bond+2);closeDialogue();toast('Bond with Iruka +2')}},{text:'What needs doing?',fn:()=>{closeDialogue();toast('Explore, talk to people, and check your journal.')}}])}
}
function finishMain(bonus){game.quest=4;game.player.bond=Math.min(100,game.player.bond+18);game.player.renown+=8;game.player.coins+=45;delete game.player.items['Sealed Scroll'];game.flags.banditsCleared=true;log('The first rift mystery is behind you—for now. Iruka made room for you at the village inn.');addXP(70);toast(`Story chapter complete · +${bonus+45} ryo`);closeDialogue();setArea('village');renderUI();save()}
function talkSakura(){if(game.quest===6){beginDialogue('Sakura','MEDICAL NIN','Three leaves, and all in good shape. I can make a restorative from this. You should keep one for yourself—field work takes more out of you than people admit.',[{text:'Thank you. I will remember that.',fn:()=>{game.quest=7;game.player.bond+=14;game.player.coins+=25;game.herbs=0;game.player.items['Bitterroot Leaf']=Math.max(0,(game.player.items['Bitterroot Leaf']||0)-3);if(!game.player.items['Bitterroot Leaf'])delete game.player.items['Bitterroot Leaf'];addItem('Field Ration');addXP(35);log('Sakura shared her knowledge and a field ration.');closeDialogue();toast('Fieldwork complete · Sakura bond +14');renderUI()}},{text:'How does the medicine work?',fn:()=>{game.player.control++;beginDialogue('Sakura','MEDICAL NIN','Careful hands, a clean leaf, and chakra used to support the body—not force it. Here, try this ration before you go.',[{text:'I will.',fn:closeDialogue}])}}])}else beginDialogue('Sakura','MEDICAL NIN',game.quest<5?'I was just about to head out. You look like you could use a proper meal.':'The leaves around the forest edge have a sharp, clean scent. Bring me three if you are heading out.',[{text:'How are things at the village?',fn:()=>{game.player.bond+=2;closeDialogue();toast('Sakura appreciates you asking.')}},{text:'I should go.',fn:closeDialogue}])}
function talkMerchant(){beginDialogue('Toma','FIELD SUPPLIES','Road food, kunai, clean wraps. Pay what you can. I do not lend, but I have been known to forget a coin or two for people who look lost.',[
{text:'Buy field ration · 25 ryo',fn:()=>{if(game.player.coins<25){toast('Not enough ryo.');return}game.player.coins-=25;addItem('Field Ration');closeDialogue();renderUI()}},
{text:'Buy 3 kunai · 18 ryo',fn:()=>{if(game.player.coins<18){toast('Not enough ryo.');return}game.player.coins-=18;game.player.kunai+=3;renderUI();closeDialogue();toast('Kunai restocked.')}},
{text:'Maybe later.',fn:closeDialogue}])}
function rest(free=false){if(!free&&game.player.coins<30){toast('The inn asks 30 ryo.');return}if(!free)game.player.coins-=30;game.player.hp=game.player.maxHp;game.player.chakra=game.player.maxChakra;game.player.stamina=game.player.maxStamina;game.day++;game.time=480;game.player.resolve++;renderUI();toast(free?'You sit quietly and gather yourself.':'A safe room, a warm meal, and one full night of sleep.');log(free?'You took a quiet moment to recover.':'You rested at the inn. A new day begins.');save()}

