+function closeDialogue(){game.dialogueOpen=false;$('#dialogue').classList.add('hidden');save()}
+function talkIruka(){if(game.quest===0){beginDialogue('Iruka','VILLAGE INSTRUCTOR','You came to in the training field with no village papers and a story about a sky that split open. I have heard stranger things—but not many. What do people call you?',[
+{text:'I am '+game.player.name+'. I came from another world.',fn:()=>{game.player.bond+=12;game.player.renown+=2;game.flags.registered=true;game.quest=1;game.player.hp=Math.max(game.player.hp,game.player.maxHp*.7);log('Iruka listened without laughing. He asked you to inspect the western forest.');addXP(15);setStatus('Someone believes you. That matters more than you expected.');closeDialogue();toast('Story updated · investigate the rift scar.')}},
+{text:'Just a traveler. I need somewhere safe.',fn:()=>{game.player.bond+=6;game.player.resolve++;game.flags.registered=true;game.quest=1;log('You kept the story close. Iruka offered shelter while you investigate the strange light.');closeDialogue();toast('Iruka points you toward the western forest.')}}])}
+else if(game.quest===3){beginDialogue('Iruka','VILLAGE INSTRUCTOR','You found it. The seal is from the old archive—but the date written beneath it is tomorrow. Someone knew the rift would open before it did. What should we do with this?',[
+{text:'Keep the village safe. I will help.',fn:()=>finishMain(18)},
+{text:'I want to understand the way home.',fn:()=>{game.player.bond+=8;game.player.resolve++;finishMain(12);log('You admitted that finding a way home matters too. Iruka did not ask you to give that up.')}}])}
+else if(game.quest===4){beginDialogue('Iruka','VILLAGE INSTRUCTOR','You have a place here as long as you want one. A small supply run could help you learn the trails—or you can take the day for yourself.',[
+{text:'I will gather herbs for Sakura.',fn:()=>{game.quest=5;game.herbs=0;game.flags.herb1=game.flags.herb2=game.flags.herb3=false;log('Iruka asked you to collect bitterroot for Sakura at the medical station.');closeDialogue();setArea('forest');toast('Fieldwork accepted · gather 3 bitterroot leaves.')}},
+{text:'Tell me more about the rift.',fn:()=>{game.player.bond+=4;beginDialogue('Iruka','VILLAGE INSTRUCTOR','The rift is not just a door. The paper you brought carries a date that has not come yet. Whatever made it may be able to change what comes next.',[{text:'I understand.',fn:closeDialogue},{text:'I need time to think.',fn:closeDialogue}])}},
+{text:'I need a quiet moment.',fn:()=>{closeDialogue();rest(true)}}])}
+else if(game.quest===6){beginDialogue('Iruka','VILLAGE INSTRUCTOR','Sakura is waiting for those herbs. She will be grateful—and she has a way of showing it.',[{text:'I will find her.',fn:()=>{closeDialogue();setArea('village');toast('Return to Sakura near the training field.')}},{text:'Later.',fn:closeDialogue}])}
+else beginDialogue('Iruka','VILLAGE INSTRUCTOR','You do not owe this village your whole life. But while you are here, we will look out for one another. That is what a village is.',[{text:'Thank you, Iruka.',fn:()=>{game.player.bond=Math.min(100,game.player.bond+2);closeDialogue();toast('Bond with Iruka +2')}},{text:'What needs doing?',fn:()=>{closeDialogue();toast('Explore, talk to people, and check your journal.')}}])}
+}
+function finishMain(bonus){game.quest=4;game.player.bond=Math.min(100,game.player.bond+18);game.player.renown+=8;game.player.coins+=45;delete game.player.items['Sealed Scroll'];game.flags.banditsCleared=true;log('The first rift mystery is behind you—for now. Iruka made room for you at the village inn.');addXP(70);toast(`Story chapter complete · +${bonus+45} ryo`);closeDialogue();setArea('village');renderUI();save()}
+function talkSakura(){if(game.quest===6){beginDialogue('Sakura','MEDICAL NIN','Three leaves, and all in good shape. I can make a restorative from this. You should keep one for yourself—field work takes more out of you than people admit.',[{text:'Thank you. I will remember that.',fn:()=>{game.quest=7;game.player.bond+=14;game.player.coins+=25;game.herbs=0;game.player.items['Bitterroot Leaf']=Math.max(0,(game.player.items['Bitterroot Leaf']||0)-3);if(!game.player.items['Bitterroot Leaf'])delete game.player.items['Bitterroot Leaf'];addItem('Field Ration');addXP(35);log('Sakura shared her knowledge and a field ration.');closeDialogue();toast('Fieldwork complete · Sakura bond +14');renderUI()}},{text:'How does the medicine work?',fn:()=>{game.player.control++;beginDialogue('Sakura','MEDICAL NIN','Careful hands, a clean leaf, and chakra used to support the body—not force it. Here, try this ration before you go.',[{text:'I will.',fn:closeDialogue}])}}])}else beginDialogue('Sakura','MEDICAL NIN',game.quest<5?'I was just about to head out. You look like you could use a proper meal.':'The leaves around the forest edge have a sharp, clean scent. Bring me three if you are heading out.',[{text:'How are things at the village?',fn:()=>{game.player.bond+=2;closeDialogue();toast('Sakura appreciates you asking.')}},{text:'I should go.',fn:closeDialogue}])}
+function talkMerchant(){beginDialogue('Toma','FIELD SUPPLIES','Road food, kunai, clean wraps. Pay what you can. I do not lend, but I have been known to forget a coin or two for people who look lost.',[
+{text:'Buy field ration · 25 ryo',fn:()=>{if(game.player.coins<25){toast('Not enough ryo.');return}game.player.coins-=25;addItem('Field Ration');closeDialogue();renderUI()}},
+{text:'Buy 3 kunai · 18 ryo',fn:()=>{if(game.player.coins<18){toast('Not enough ryo.');return}game.player.coins-=18;game.player.kunai+=3;renderUI();closeDialogue();toast('Kunai restocked.')}},
+{text:'Maybe later.',fn:closeDialogue}])}
+function rest(free=false){if(!free&&game.player.coins<30){toast('The inn asks 30 ryo.');return}if(!free)game.player.coins-=30;game.player.hp=game.player.maxHp;game.player.chakra=game.player.maxChakra;game.player.stamina=game.player.maxStamina;game.day++;game.time=480;game.player.resolve++;renderUI();toast(free?'You sit quietly and gather yourself.':'A safe room, a warm meal, and one full night of sleep.');log(free?'You took a quiet moment to recover.':'You rested at the inn. A new day begins.');save()}

