function rest(free=false){if(!free&&game.player.coins<30){toast('The inn asks 30 ryo.');return}if(!free)game.player.coins-=30;game.player.hp=game.player.maxHp;game.player.chakra=game.player.maxChakra;game.player.stamina=game.player.maxStamina;game.day++;game.time=480;game.player.resolve++;renderUI();toast(free?'You sit quietly and gather yourself.':'A safe room, a warm meal, and one full night of sleep.');log(free?'You took a quiet moment to recover.':'You rested at the inn. A new day begins.');save()}
function box(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function seeded(x,y,s=0){const v=Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453;return v-Math.floor(v)}
function drawGround(){const forest=game.area==='forest';box(0,0,960,600,forest?'#557052':'#758867');for(let y=0;y<13;y++)for(let x=0;x<20;x++){let r=seeded(x,y,forest?5:3),xx=x*48,yy=y*48;if(forest){box(xx,yy,48,48,r>.52?'#587254':'#5c7658');if(r>.57){box(xx+8,yy+11,3,2,'#71866a');box(xx+31,yy+35,5,2,'#4d674f')}if(r>.88){box(xx+19,yy+15,3,8,'#74885d');box(xx+17,yy+17,7,3,'#779361')}}else{box(xx,yy,48,48,r>.5?'#79906d':'#73876a');if(r>.52){box(xx+8,yy+12,3,2,'#8e9b71');box(xx+31,yy+37,3,2,'#647f60')}if(r>.84){box(xx+18,yy+17,3,6,'#a5a07a');box(xx+15,yy+19,8,2,'#bea976')}}}
if(forest){box(0,270,960,73,'#948c72');box(0,278,960,5,'#b4a78a');box(0,337,960,4,'#776f5c');for(let x=0;x<960;x+=48){if(x<120||x>880||seeded(x,4,8)>.52)tree(x+seeded(x,8)*15,70+seeded(x,5)*48,seeded(x,9));if(x<175||x>850)tree(x+5,455+seeded(x,6)*22,seeded(x,9))}for(const [x,y] of [[225,230],[685,218],[730,485],[365,476],[164,430]]){box(x,y,9,4,'#c1ad77');box(x+5,y+5,5,3,'#a09161')}}else{drawVillagePaths();drawHouse(64,58,150,108,'#b57855');drawHouse(756,58,145,112,'#c0a66f');drawHouse(743,426,151,108,'#9b795a');drawHouse(46,428,138,110,'#758672');drawTrainingArea();for(let x=14;x<950;x+=42){if((x<230||x>735)&&!(x>840&&x<930))fence(x,397)}tree(260,100,.3);tree(663,104,.7);tree(217,524,.5);tree(683,533,.4);drawInnSign()}}
function drawVillagePaths(){ctx.fillStyle='#b9aa89';ctx.beginPath();ctx.moveTo(0,265);ctx.lineTo(960,265);ctx.lineTo(960,345);ctx.lineTo(0,345);ctx.fill();ctx.beginPath();ctx.moveTo(426,600);ctx.lineTo(426,300);ctx.lineTo(535,300);ctx.lineTo(535,600);ctx.fill();box(0,263,960,3,'#cabc9c');box(0,344,960,3,'#9c9278');for(let i=0;i<18;i++){let x=i*58;box(x,286+(i%2)*18,21,2,'#d0c0a0')}}
function drawHouse(x,y,w,h,roof){box(x+8,y+20,w,h-17,'#d6c6a5');box(x+13,y+25,w-10,h-20,'#bba987');box(x+3,y+10,w-6,28,roof);box(x,y+30,w,7,shadeColor(roof,-25));box(x+12,y+42,29,25,'#4b5650');box(x+16,y+46,21,17,'#8eaa9b');box(x+w-45,y+47,28,39,'#765541');box(x+w-42,y+51,22,35,'#9e7b5d');box(x+14,y+h-15,w-20,6,'#88765c');box(x+22,y+4,w-38,5,'#dbc59b');for(let i=0;i<3;i++)box(x+25+i*24,y+16,4,3,'#e1caa0')}
function shadeColor(hex,amount){let n=parseInt(hex.slice(1),16),r=clamp((n>>16)+amount,0,255),g=clamp(((n>>8)&255)+amount,0,255),b=clamp((n&255)+amount,0,255);return '#'+(1<<24|r<<16|g<<8|b).toString(16).slice(1)}
function tree(x,y,r=0){let s=1+r*.22;box(x+13*s,y+25*s,9*s,25*s,'#68533d');box(x+7*s,y+21*s,20*s,6*s,'#786046');box(x+4*s,y+9*s,28*s,24*s,'#3f604a');box(x+10*s,y+1*s,23*s,23*s,'#52734f');box(x,y+15*s,19*s,18*s,'#49694b');box(x+9*s,y+7*s,4*s,4*s,'#789164');box(x+25*s,y+12*s,4*s,4*s,'#6f875c');box(x+5*s,y+25*s,9*s,5*s,'#3d5a43')}
function fence(x,y){box(x,y,3,18,'#8d7655');box(x+22,y,3,18,'#8d7655');box(x,y+3,25,3,'#a58a61');box(x,y+11,25,3,'#a58a61')}
function drawTrainingArea(){box(344,367,270,7,'#617b5b');for(let i=0;i<5;i++){const x=361+i*48;box(x,356,6,36,'#6c5038');box(x-5,351,16,6,'#9c8060');box(x-2,359,9,4,'#9a6349')}box(447,220,57,4,'#6e5942');box(450,224,5,22,'#745e44');box(497,224,5,22,'#745e44');box(452,230,47,3,'#ad976e')}
function drawInnSign(){box(704,389,3,30,'#74543b');box(682,391,48,24,'#a7583e');ctx.fillStyle='#f0d7ad';ctx.font='13px serif';ctx.fillText('宿',696,408)}
function drawProp(n,id){if(id==='rift'){ctx.globalAlpha=.7+Math.sin(performance.now()/180)*.18;box(n.x-16,n.y-30,31,2,'#b8d7e2');box(n.x-8,n.y-25,3,42,'#9cc3d8');box(n.x+7,n.y-31,3,45,'#c8dff0');ctx.globalAlpha=1;box(n.x-11,n.y+17,28,3,'#665643');return}if(id==='cache'){box(n.x-17,n.y-8,34,22,'#72573e');box(n.x-13,n.y-15,27,11,'#8c714d');box(n.x-10,n.y-12,20,4,'#b29b6b');return}if(id.startsWith('herb')){box(n.x,n.y,3,10,'#4e754e');box(n.x-5,n.y+2,6,3,'#84a25f');box(n.x+2,n.y-3,6,4,'#92a365');box(n.x-4,n.y-4,4,3,'#c7a86f');return}}
function drawPerson(x,y,opts={}){const p=opts.player?game.player:opts;const step=opts.player&&game.walk?Math.sin(game.walk)*2:0;box(x-10,y+11,21,5,'#23332c55');box(x-7,y+3+step,5,10,opts.player?'#37423f':'#373a37');box(x+2,y+3-step,5,10,opts.player?'#303b39':'#41413d');box(x-9,y+12,8,3,'#41362f');box(x+1,y+12,8,3,'#41362f');box(x-10,y-12,20,17,opts.player?p.outfit:(opts.color||'#526a68'));box(x-13,y-8,5,13,opts.player?p.outfit:(opts.color||'#526a68'));box(x+8,y-8,5,13,opts.player?p.outfit:(opts.color||'#526a68'));box(x-6,y-25,12,13,opts.player?p.skin:'#bd886b');box(x-8,y-29,16,9,opts.player?p.hair:'#342e2a');box(x-8,y-24,3,5,opts.player?p.hair:'#342e2a');box(x+5,y-23,2,2,'#242524');if(opts.player){box(x-11,y-15,22,4,'#b6a887');box(x-2,y-14,4,2,'#555c56');if(game.shade){ctx.globalAlpha=.6;box(x-18,y-8,36,13,'#b4d7dc');ctx.globalAlpha=1}}else{box(x-10,y-15,20,3,'#b8a47f')}}
function drawEnemy(e){box(e.x-12,e.y+12,24,4,'#24312d66');box(e.x-9,e.y-13,18,26,e.hit?'#b56550':'#554b48');box(e.x-6,e.y-27,12,14,'#a87860');box(e.x-8,e.y-31,17,8,'#302b2a');box(e.x-5,e.y-21,3,2,'#e5bd7b');box(e.x+3,e.y-21,3,2,'#e5bd7b');box(e.x-14,e.y-8,27,4,'#373532');if(e.hp<e.max){box(e.x-14,e.y-36,28,3,'#352f2d');box(e.x-14,e.y-36,28*e.hp/e.max,3,'#bd5945')}}
function drawWorld(){drawGround();const renderables=[];if(game.area==='village'){for(const [id,n] of Object.entries(npcs))if(!id.startsWith('herb'))renderables.push({y:n.y,fn:()=>id==='gate'?drawPerson(n.x,n.y,{color:'#455858'}):drawPerson(n.x,n.y,{color:n.color})});renderables.push({y:220,fn:()=>drawProp({x:112,y:215},'rift')})}else{for(const [id,n] of Object.entries(npcs))if(id.startsWith('herb')&&!game.flags[id])renderables.push({y:n.y,fn:()=>drawProp(n,id)});if(game.quest===2)renderables.push({y:285,fn:()=>drawProp(npcs.cache,'cache')});if(game.quest===1)renderables.push({y:215,fn:()=>drawProp(npcs.rift,'rift')});game.enemies.forEach(e=>renderables.push({y:e.y,fn:()=>drawEnemy(e)}))}renderables.push({y:game.player.y,fn:()=>drawPerson(game.player.x,game.player.y,{player:true})});renderables.sort((a,b)=>a.y-b.y).forEach(o=>o.fn());game.projectiles.forEach(o=>{box(o.x-4,o.y-2,9,3,'#d9d4c2');box(o.x,o.y-3,4,3,'#ab5540')});game.particles.forEach(p=>{ctx.globalAlpha=Math.max(0,p.life);box(p.x,p.y,3,3,p.color);ctx.globalAlpha=1});if(game.time>1150||game.time<330){let alpha=game.time>1150?Math.min(.4,(game.time-1150)/300):Math.min(.4,(330-game.time)/330);ctx.fillStyle=`rgba(18,30,45,${alpha})`;ctx.fillRect(0,0,960,600)}if(game.damageFlash>0){ctx.fillStyle=`rgba(180,45,35,${game.damageFlash*.2})`;ctx.fillRect(0,0,960,600)}drawAmbient()}
function drawAmbient(){for(let i=0;i<15;i++){let x=(i*173+game.time*1.1)%980,y=(i*97+Math.sin(game.time/80+i)*35)%600;ctx.globalAlpha=.13;box(x,y,2,2,game.area==='forest'?'#d7e0b0':'#efe1a4')}ctx.globalAlpha=1}

