28: function renderInventory(){const entries=Object.entries(game.player.items||{});$('#item-count').textContent=entries.reduce((a,[,n])=>a+n,0);$('#pack-weight').textContent=`${entries.reduce((a,[,n])=>a+n,0)} / 20`;const icons={'Field Ration':'◒','Bitterroot Leaf':'❋','Sealed Scroll':'▤','Old Coin':'◉'};$('#inventory-list').innerHTML=entries.length?entries.map(([name,n])=>`<div class="inventory-item"><div class="item-icon">${icons[name]||'◇'}</div><div><b>${escapeHTML(name)}</b><small>${name==='Field Ration'?'Restores vitality':name==='Bitterroot Leaf'?'Restores chakra':name==='Sealed Scroll'?'A message from another time':'A small keepsake'}</small></div><span class="item-qty">×${n}</span>${['Field Ration','Bitterroot Leaf'].includes(name)?`<button class="use-item" data-item="${name}">USE</button>`:''}</div>`).join(''):'<p class="muted-note">Nothing but dust in your pack.</p>';$$('.use-item').forEach(b=>b.onclick=()=>useItem(b.dataset.item))}
29: function renderUI(){const p=game.player;$('#player-name').textContent=p.name;$('#player-rank').textContent=`${game.flags.registered?'GENIN':'UNREGISTERED'} · LV ${p.level}`;$('#portrait').textContent=(p.name||'?').slice(0,1).toUpperCase();$('#portrait').style.background=p.hair;$('#hp-text').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}`;$('#chakra-text').textContent=`${Math.ceil(p.chakra)} / ${p.maxChakra}`;$('#stamina-text').textContent=`${Math.ceil(p.stamina)} / ${p.maxStamina}`;$('#hp-bar').style.width=`${100*p.hp/p.maxHp}%`;$('#chakra-bar').style.width=`${100*p.chakra/p.maxChakra}%`;$('#stamina-bar').style.width=`${100*p.stamina/p.maxStamina}%`;$('#stat-level').textContent=String(p.level).padStart(2,'0');$('#stat-xp').textContent=`${p.xp} / ${p.level*100}`;$('#stat-renown').textContent=p.renown;$('#stat-coin').textContent=`${p.coins} RYO`;$('#stat-power').textContent=p.power;$('#stat-control').textContent=p.control;$('#stat-resolve').textContent=p.resolve;$('#bond-value').textContent=`${p.bond} / 100`;$('#bond-bar').style.width=`${p.bond}%`;$('#kunai-count').textContent=p.kunai;$('#bond-note').textContent=p.bond<20?'A first impression is waiting to be made.':p.bond<60?'Iruka has begun to trust you with the truth.':'You have earned a place at the village table.';renderInventory();renderJournal();updateQuest();updateMiniMap()}
