function drawWorld(){drawGround();const renderables=[];if(game.area==='village'){for(const [id,n] of Object.entries(npcs))if(!id.startsWith('herb'))renderables.push({y:n.y,fn:()=>id==='gate'?drawPerson(n.x,n.y,{color:'#455858'}):drawPerson(n.x,n.y,{color:n.color})});renderables.push({y:220,fn:()=>drawProp({x:112,y:215},'rift')})}else{for(const [id,n] of Object.entries(npcs))if(id.startsWith('herb')&&!game.flags[id])renderables.push({y:n.y,fn:()=>drawProp(n,id)});if(game.quest===2)renderables.push({y:285,fn:()=>drawProp(npcs.cache,'cache')});if(game.quest===1)renderables.push({y:215,fn:()=>drawProp(npcs.rift,'rift')});game.enemies.forEach(e=>renderables.push({y:e.y,fn:()=>drawEnemy(e)}))}renderables.push({y:game.player.y,fn:()=>drawPerson(game.player.x,game.player.y,{player:true})});renderables.sort((a,b)=>a.y-b.y).forEach(o=>o.fn());game.projectiles.forEach(o=>{box(o.x-4,o.y-2,9,3,'#d9d4c2');box(o.x,o.y-3,4,3,'#ab5540')});game.particles.forEach(p=>{ctx.globalAlpha=Math.max(0,p.life);box(p.x,p.y,3,3,p.color);ctx.globalAlpha=1});if(game.time>1150||game.time<330){let alpha=game.time>1150?Math.min(.4,(game.time-1150)/300):Math.min(.4,(330-game.time)/330);ctx.fillStyle=`rgba(18,30,45,${alpha})`;ctx.fillRect(0,0,960,600)}if(game.damageFlash>0){ctx.fillStyle=`rgba(180,45,35,${game.damageFlash*.2})`;ctx.fillRect(0,0,960,600)}drawAmbient()}
function drawAmbient(){for(let i=0;i<15;i++){let x=(i*173+game.time*1.1)%980,y=(i*97+Math.sin(game.time/80+i)*35)%600;ctx.globalAlpha=.13;box(x,y,2,2,game.area==='forest'?'#d7e0b0':'#efe1a4')}ctx.globalAlpha=1}
function collides(x,y){const p={x,y};if(x<12||x>948||y<30||y>575)return false;if(game.area==='village'){const obstacles=[[64,58,150,108],[756,58,145,112],[743,426,151,108],[46,428,138,110],[344,365,270,7]];if(obstacles.some(([a,b,w,h])=>x>a-15&&x<a+w+15&&y>b-8&&y<b+h))return true;if(x>810&&y>380&&y<420)return true}else{if((x<120||x>880)&&!(y>270&&y<350))return true;for(const [a,b] of [[225,230],[685,218],[730,485],[365,476],[164,430]])if(Math.hypot(x-a,y-b)<18)return true}return false}
function move(dt){const p=game.player;let dx=0,dy=0;if(game.keys.ArrowUp||game.keys.KeyW||game.touchUp)dy--;if(game.keys.ArrowDown||game.keys.KeyS||game.touchDown)dy++;if(game.keys.ArrowLeft||game.keys.KeyA||game.touchLeft)dx--;if(game.keys.ArrowRight||game.keys.KeyD||game.touchRight)dx++;if(dx||dy){const len=Math.hypot(dx,dy);dx/=len;dy/=len;let speed=game.keys.ShiftLeft||game.keys.ShiftRight||game.touchDash?215:135;if(speed>180&&p.stamina>0)p.stamina=Math.max(0,p.stamina-34*dt);else speed=135;if(dx)p.dir=dx>0?'right':'left';else p.dir=dy>0?'down':'up';const nx=p.x+dx*speed*dt,ny=p.y+dy*speed*dt;if(!collides(nx,p.y))p.x=nx;if(!collides(p.x,ny))p.y=ny;game.walk+=dt*12;if(Math.random()<dt*11)game.particles.push({x:p.x+rnd(-8,8),y:p.y+14,life:.45,color:'#d0c19a'})}else{p.stamina=Math.min(p.maxStamina,p.stamina+19*dt)}if(game.area==='village'&&p.x>938&&p.y>260&&p.y<360)setArea('forest');else if(game.area==='forest'&&p.x<18&&p.y>260&&p.y<360)setArea('village');p.x=clamp(p.x,12,948);p.y=clamp(p.y,28,578)}
function damageEnemy(e,n){e.hp-=n;e.hit=true;setTimeout(()=>e.hit=false,120);for(let i=0;i<5;i++)game.particles.push({x:e.x+rnd(-10,10),y:e.y+rnd(-20,5),life:.5,color:'#bf7256'});if(e.hp<=0){game.enemies=game.enemies.filter(a=>a!==e);game.kills++;game.player.coins+=7;game.player.xp+=22;game.player.stamina=Math.min(game.player.maxStamina,game.player.stamina+7);toast(`${e.kind} repelled · +7 ryo`);log(`You drove off a rogue shinobi. (${game.kills} cleared)`);if(game.kills>=2&&game.quest===2)toast('The path to the camp is clear.');if(game.quest>=5){game.flags.banditsCleared=true}renderUI();save()}}
function attack(){const p=game.player;if(game.attackCd>0)return;if(p.stamina<12){toast('Too exhausted to strike.');return}p.stamina-=12;game.attackCd=.36;const e=game.enemies.find(a=>Math.hypot(a.x-p.x,a.y-p.y)<62);if(e){damageEnemy(e,14+p.power*2);toast('A clean strike.')}else{for(let i=0;i<3;i++)game.particles.push({x:p.x+rnd(-24,24),y:p.y-10+rnd(-18,10),life:.23,color:'#e6d4a3'})}}
function jutsu(){const p=game.player;if(p.chakra<16){toast('Not enough chakra.');return}p.chakra-=16;game.shade=true;setTimeout(()=>game.shade=false,380);game.attackCd=Math.max(game.attackCd,.35);const hits=game.enemies.filter(e=>Math.hypot(e.x-p.x,e.y-p.y)<112);hits.forEach(e=>damageEnemy(e,23+p.control*3));if(!hits.length)toast('Shadow clone feint · no one in range.');else toast(`Shadow clone · ${hits.length} target${hits.length>1?'s':''} struck.`);renderUI()}
function throwKunai(){const p=game.player;if(!p.kunai){toast('Out of kunai.');return}p.kunai--;const e=game.enemies.slice().sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(e&&Math.hypot(e.x-p.x,e.y-p.y)<320){game.projectiles.push({x:p.x,y:p.y-8,target:e,speed:440});}else toast('No target in range. Kunai spent.');renderUI()}
function enemyAI(dt){const p=game.player;for(const e of [...game.enemies]){e.cool=Math.max(0,e.cool-dt);const d=Math.hypot(p.x-e.x,p.y-e.y);if(d>36){let vx=(p.x-e.x)/(d||1),vy=(p.y-e.y)/(d||1);let nx=e.x+vx*39*dt,ny=e.y+vy*39*dt;if(!collides(nx,e.y))e.x=nx;if(!collides(e.x,ny))e.y=ny}else if(e.cool===0){e.cool=1.2;p.hp=Math.max(0,p.hp-(7+Math.max(0,game.day-1)));game.damageFlash=1;for(let i=0;i<5;i++)game.particles.push({x:p.x+rnd(-14,14),y:p.y+rnd(-16,10),life:.5,color:'#b4483e'});toast('A hit landed. Create some distance.');if(p.hp<=0)knockout();renderUI()}}}
function knockout(){pReset();function pReset(){game.player.hp=Math.max(1,Math.floor(game.player.maxHp*.55));game.player.coins=Math.max(0,game.player.coins-15);game.enemies=[];setArea('village');toast('You wake at the medical station. 15 ryo lost.');log('Sakura helped you recover after the fight. Your pack and story are safe.');save()}}
function update(dt){if(!game.dialogueOpen&&!game.menuOpen)move(dt);game.attackCd=Math.max(0,game.attackCd-dt);game.damageFlash=Math.max(0,game.damageFlash-dt*2);if(!game.dialogueOpen&&!game.menuOpen)game.time+=dt*1.5;if(game.time>=1440){game.time-=1440;game.day++;}for(const o of game.projectiles){if(!o.target||!game.enemies.includes(o.target))continue;const d=Math.hypot(o.target.x-o.x,o.target.y-o.y);if(d<o.speed*dt+9){damageEnemy(o.target,24+game.player.control*2);o.target=null}else{o.x+=(o.target.x-o.x)/d*o.speed*dt;o.y+=(o.target.y-o.y)/d*o.speed*dt}}game.projectiles=game.projectiles.filter(o=>o.target);game.particles.forEach(p=>{p.life-=dt;p.y-=dt*12});game.particles=game.particles.filter(p=>p.life>0);if(game.area==='forest'&&game.enemies.length&&!game.dialogueOpen&&!game.menuOpen)enemyAI(dt);if(game.quest===5)$('#journal-objective').textContent=`Gather bitterroot from the forest (${Math.min(3,game.herbs)} / 3).`;game.near=nearest();const hint=$('#interaction-hint');if(game.near&&!game.dialogueOpen){hint.classList.remove('hidden');hint.style.left=`${game.near.n.x/960*100}%`;hint.style.top=`${game.near.n.y/600*100}%`;hint.querySelector('span').textContent=game.near.id==='enemy'?'Threat nearby':game.near.id==='gate'?'Enter forest':game.near.id.startsWith('herb')?'Gather':'Interact'}else hint.classList.add('hidden');$('#clock-label').textContent=`DAY ${game.day} · ${clock()}`;if(performance.now()-game.saveTime>10000){game.saveTime=performance.now();save()}game.uiTimer=(game.uiTimer||0)+dt;if(game.uiTimer>=.2){game.uiTimer=0;renderUI()}drawWorld();requestAnimationFrame(frame)}
function frame(now){if(!game.started)return;const dt=Math.min(.04,(now-game.last)/1000||0);game.last=now;update(dt)}

