20: function setQuest(title,obj){$('#quest-title').textContent=title;$('#quest-objective').textContent=obj;$('#journal-title').textContent=title;$('#journal-objective').textContent=obj}
21: function addXP(n){game.xp+=n;while(game.xp>=game.level*100){game.xp-=game.level*100;game.level++;game.maxHp+=8;game.maxChakra+=5;game.power++;game.hp=game.maxHp;game.chakra=game.maxChakra;$('#level-toast').classList.remove('hidden');setTimeout(()=>$('#level-toast').classList.add('hidden'),2100);toast(`Level ${game.level} · your resolve deepens.`)}renderUI();save()}
22: function addItem(name,n=1){game.player.items[name]=(game.player.items[name]||0)+n;toast(`${name} ×${n} added to your pack`);renderUI()}
23: function useItem(name){const n=game.player.items[name]||0;if(!n)return false;game.player.items[name]--;if(game.player.items[name]<=0)delete game.player.items[name];if(name==='Field Ration'){game.player.hp=Math.min(game.player.maxHp,game.player.hp+32);game.player.stamina=game.player.maxStamina;toast('A quiet moment. Vitality restored.')}else if(name==='Bitterroot Leaf'){game.player.chakra=Math.min(game.player.maxChakra,game.player.chakra+18);toast('The bitter tea steadies your chakra.')}renderUI();save();return true}
24: function save(){try{const p={...game,keys:{},enemies:[],projectiles:[],particles:[],near:null};localStorage.setItem('riftbound-save',JSON.stringify(p));$('#save-btn').classList.add('saved');setTimeout(()=>$('#save-btn').classList.remove('saved'),700)}catch(e){}}
25: function load(){try{const raw=localStorage.getItem('riftbound-save');if(!raw)return false;const d=JSON.parse(raw);Object.assign(game,d);game.keys={};game.enemies=[];game.projectiles=[];game.particles=[];game.started=true;setArea(game.area,false);return true}catch(e){return false}}
